"""Generate the delivery report only after all runtime and installation evidence exists."""
from pathlib import Path
import json,statistics,math,re
root=Path(__file__).resolve().parents[1];out=root/'test-results'
def read(name):return json.loads((out/name).read_text(encoding='utf-8-sig'))
def stat(a):
 a=sorted(a);return f'{statistics.median(a):.1f} / {a[math.ceil(.95*len(a))-1]:.1f} / {max(a):.1f}'
r=read('m5-final.json');memory=read('m5-final-memory.json');idle=read('m5-final-idle.json');startup=read('m5-final-startup.json');stress=read('m5-stress-memory.json');install=read('install-m5/acceptance.json');native=read('install-m5/runtime.json')
assert len(r['datasets'])==3 and all(len(v['all_exact'])==20 for v in r['datasets'].values())
assert install['opt_in_cleanup'] and install['preexisting_personal_data_restored'] and install['installed_exe_matches_except_bundle_marker'] and native['command_line_to_existing_instance']
assert not r['errors']
for name in ['smoke.json','m2-smoke.json','m3-smoke.json','m4-smoke.json']:assert not read(name)['errors']
exe=(root/'src-tauri/target/release/ParquetLens.exe').stat().st_size;setup=(root/'src-tauri/target/release/bundle/nsis/ParquetLens_0.6.0_x64-setup.exe').stat().st_size
lines=['## M5 基准与优化：0.6.0，2026-10-30','',f'交付 exe **{exe:,} 字节（{exe/1e6:.2f} MB）**，NSIS **{setup:,} 字节（{setup/1e6:.2f} MB）**。exe 比 0.5.1 缩小 {(1-exe/17891840)*100:.1f}%；12 MB / 8 MB 体积目标均达标。功能回归和安装验收通过；性能目标并非全部达标，见下表与限制。','','### 改动与取舍','','- release 改为 opt-level="z"，保留 fat LTO、单 codegen unit、strip、panic="unwind"、所有类型和五种压缩格式。没有 UPX、功能裁剪或数据迁移。','- UTC 枚举分页借用已有结果，避免整份结果克隆；摘要直接复制元数据，不先复制全部枚举值再丢弃。','- 高基数/资源上限终止时释放计数容器容量；前端去重同一请求的事件与最终响应，避免重复取页和刷新。','- 以上减少临时复制和滞留容量，但不等于已达到 150 MB 空闲目标。标准基准受到 WebView2、分配器和界面生命周期影响，不把单次波动归因于某一优化。','','| 构建 | exe MB | 原样本全列枚举中位数 ms | 比较次数 |','|---|---:|---:|---:|']
for label,title in [('m5-baseline','0.5.1 / opt=3'),('m5-s','M5 候选 / opt=s'),('m5-z','M5 候选 / opt=z')]:
 a=read(label+'.json');lines.append(f"| {title} | {a['bytes']/1e6:.2f} | {statistics.median(a['datasets']['benchmark']['all_exact']):.1f} | {a['reps']} |")
lines+=['','选择 z 是体积优先的明确取舍：扫描和抽样较 opt=3 变慢，但本机最终扫描/导出指标仍在目标内。候选为 0.5.1 版本号的独立离线测试构建；以下结果来自最终 0.6.0 的精确 SHA256 对应 exe。','','### 环境与测量方法','','Windows 11 26200、Ryzen 7 6800H（8核16线程）、约16 GB物理内存、D盘NTFS、WebView2 156.0.4314.50；Rust/Cargo 1.99.1、Node 24.22.0、Python 3.12.14。应用任务与本项目编译串行；保留用户其他桌面程序，不把本机成绩外推到其他机器。','每个文件先完整预热一轮，再记录20轮；不剔除慢样本。下表均为 **中位数 / P95 / 最大值，单位 ms**，P95 使用 nearest-rank。IPC 是真实 release 后端；界面计时在页面内发起操作并等目标DOM及两帧，含WebView2/CDP开销。预览完整1000行分两次500行读取；首屏显示单列为500行页的虚拟表格。','原样本 803,958,825字节、2000万行、50列、80 RG、Snappy，其中45列组内恒定，可能走footer捷径。混合 Snappy 819,175,011字节、Zstd 820,331,058字节，各1000万行、50列、40 RG；包含随机int64、组内混合100种分类值、约5% NULL、字典字符串。混合数据固定种子20261030。PyArrow独立计数逐值校验；两种压缩的首/尾完整RG相等。','','**没有重启计算机或清空系统缓存。真正冷启动、冷磁盘打开均未测，不能以预热或新WebView配置代替。**']
metrics=[('open_metadata_ipc','footer元数据 IPC','—'),('open_display','打开至列清单显示','300'),('head_1000_ipc','头部1000行完整 IPC','1000'),('uniform_1000_ipc','均匀1000行完整 IPC','2000'),('head_display','头部预览首屏500行','—'),('uniform_display','均匀预览首屏500行','—'),('xlsx_1000x50','xlsx 1000×50','2000'),('single_exact','单列全量枚举','5000'),('all_exact','50列全量枚举','15000'),('cache_ipc','缓存请求 IPC','—'),('cache_display','缓存命中至枚举显示','200')]
for name,v in r['datasets'].items():
 lines+=['',f'### {name}：20 次','','| 项目 | 中位数 / P95 / 最大值 ms | 目标 ms |','|---|---:|---:|']
 for key,title,target in metrics:lines.append(f"| {title} | {stat(v.get(key,v['ui'].get(key)))} | {target} |")
lines+=['','### 启动与内存','','| 启动类型 | 次数 | 中位数 / P95 / 最大值 ms |','|---|---:|---:|']
for mode,title in [('first-webview-profile','新WebView配置，热系统缓存'),('existing-webview-profile','已有WebView配置，热系统缓存')]:lines.append(f"| {title} | 5 | {stat([v['ms'] for v in startup['results'] if v['mode']==mode])} |")
lines+=['','无CDP正常启动5次，8秒和20秒记录，正常关闭并重启；以下采用20秒值，未强制GC、清理工作集或交换到磁盘以压低读数。','','| 内存口径 | 中位数 / P95 / 最大值 MB |','|---|---:|',f"| 空闲进程树 Private Bytes | {stat([v['at_20s']['private']/1e6 for v in idle['runs']])} |",f"| 空闲进程树 Working Set 求和 | {stat([v['at_20s']['working']/1e6 for v in idle['runs']])} |",'',f"标准全程采样峰值 Private Bytes {memory['max_private_bytes']/1e6:.2f} MB，Working Set {memory['max_working_bytes']/1e6:.2f} MB。50ms左右采样，可能漏掉更短峰值；工作集求和可能重复计共享页。扫描与UI、多标签阶段分别记录如下。",'','| 阶段 | Private Bytes峰值 MB | Working Set峰值 MB |','|---|---:|---:|']
for phase,v in sorted(memory['phases'].items()):lines.append(f"| {phase} | {v['max_private_bytes']/1e6:.2f} | {v['max_working_bytes']/1e6:.2f} |")
baseline_memory=read('m5-baseline-memory.json');lines+=['',f"同场景0.5.1全程峰值Private Bytes为{baseline_memory['max_private_bytes']/1e6:.2f} MB，本版为{memory['max_private_bytes']/1e6:.2f} MB；本轮没有观察到整体峰值下降。Private Bytes低于1 GB，工作集求和超过1 GB时也保留原值，不混淆口径。"]
life=r['lifecycle'];lines+=['', '十轮各打开10个标签再全部关闭，关闭后Private Bytes（MB）：'+', '.join(f"{v['closed']['private']/1e6:.1f}" for v in life['rounds'])+f"。额外静置30秒后为 {life['after_30s_idle']['private']/1e6:.1f} MB。该有限循环不能证明不存在长期泄漏。",f"另外对每份约1.64 GB的Snappy/Zstd文件各预热一轮、测一轮（2000万行/50列/80 RG），峰值Private Bytes {stress['max_private_bytes']/1e6:.2f} MB，Working Set {stress['max_working_bytes']/1e6:.2f} MB。压力样本不混入20轮标准统计。",'','### 未达标项与边界','','- 空闲≤150 MB未达标：进程树主要由WebView2占用，Rust结果复制优化不能消除浏览器基线；本轮没有禁用安全功能、替换渲染器或用工作集清理冒充内存优化。','- 缓存显示和打开界面存在超过目标的样本；以各表P95/最大值为准。缓存IPC远小于总显示耗时，余量包含布局、绘制、事件调度；z又增加后端处理耗时。不能把一次IPC返回时间当作用户可见完成时间。','- 真正冷系统缓存/重启后启动未测，需要另行安排；当前结果不能证明1秒冷启动和冷磁盘打开目标已达成。新WebView配置的实测启动也有超过1秒的样本，见上表。','- 真正Win10 1809、UNC共享、无WebView2机器仍未覆盖；本轮为本机Windows 11验收。','','### 测试与安装验收','','58项Rust测试、2项前端测试、Svelte检查、fmt、Clippy全部通过。新增摘要完整性、停止计数后共享预算不污染其他列，以及Snappy/Gzip/Zstd/LZ4/Brotli数据页解码回归。','最终exe完成M1–M4真实运行回归；XLSX/XML、CSV与PyArrow独立回读，枚举缓存、cap、快速/全量、取消与取消后重试、时区/精度、设置/主题、多标签、单实例均验证。原生拖放/保存对话框返回值在Tauri边界注入，不代表物理鼠标拖放或逐项手工点选对话框验收。','真实NSIS验收链路：0.6.0全新安装→默认卸载；0.4.0→0.5.0→0.5.1→0.6.0升级；重装；默认保留个人数据卸载；显式清理卸载。0.6.0安装/升级/重装/卸载均不注册右键菜单；旧版所属菜单由兼容清理逻辑删除，默认文件关联不变。安装版与便携版分别记录SHA256：仅Tauri内置打包类型标记有3字节差异（UNK→NSS），归一化该标记后逐字节一致。初次逐字节相同断言因此失败，查明框架行为后修正验收规则；另修正验收脚本恢复注册表时的只读句柄写入问题。原数据校验恢复后从头完整重跑安装链路通过，应用与安装包无需重构建。','已安装exe验证中文/空格路径、第二实例转交、设置保留与不自动恢复标签。测试安装最终卸载；原个人文件、WebView文件和原安装偏好已校验恢复，未留下测试常驻实例。原始备份留在test-results，不纳入交付。','','### 复现与证据','','`./scripts/verify.ps1` → `./scripts/build.ps1` → `./scripts/test-m5.ps1`。大样本生成：`bench/generate.py`、`bench/generate_mixed.py`；脚本将运行真实窗口，需先正常关闭已有ParquetLens。生成器默认生成约820MB混合文件；压力文件复现：`.venv/Scripts/python.exe bench/generate_mixed.py --groups 80 --prefix stress`；数据规格见verification/m5-data-oracle.json。','安装脚本 `scripts/install-m5.ps1 -Phase Install`、`node scripts/installed-m5.mjs`、`scripts/install-m5.ps1 -Phase Uninstall` 会真实修改当前用户安装状态，内含已有安装保护、个人数据备份/哈希恢复；不要在日常窗口运行中执行。','交付的verification包含原始20次值、候选比较、内存分段、环境、测试日志和安装验收JSON；不包含测试数据、用户缓存或WebView配置。SHA256SUMS.txt校验交付文件，SOURCE-SHA256SUMS.txt记录对应源文件。']
text='\n'.join(lines)+'\n'
(out/'m5-report.md').write_text(text,encoding='utf-8')
print('Generated M5 report from completed evidence')
